"use strict";(self.webpackChunkdoc_serveradmincore=self.webpackChunkdoc_serveradmincore||[]).push([[3361],{4782:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"1-1-0","metadata":{"permalink":"/changelog/1-1-0","source":"@site/changelog/2026-11-27-1-1-0.md","title":"Server Admin Core 1.1.0","description":"GENERAL","date":"2026-11-27T00:00:00.000Z","tags":[],"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Server Admin Core 1.1.0","slug":"1-1-0"},"unlisted":false,"nextItem":{"title":"Server Admin Core 1.0.1","permalink":"/changelog/1-0-1"}},"content":"## **GENERAL**\\n\\n- New module **ServerAdminCoreRemote** for [remote control](/docfiles/remote/overview) of dedicated servers\\n- IP addresses are removed from all REST and WebSocket output unless the token\'s group has `serveradmincore.info.ip`\\n- Free [companion tools](/docfiles/remote/companion-tools): watchdog, Discord bot and web panel, downloaded separately\\n\\n## **ADDED**\\n\\n- Source **RCON** listener, compatible with mcrcon and other Source RCON clients\\n- **REST API** with health, status, players, bans, logs and command endpoints\\n- **WebSocket event stream** with token authentication and per-connection permissions\\n- **API tokens** with the `token create`, `token list` and `token revoke` commands\\n- **Managed mode** for restarts under the watchdog, with a restart flag file\\n- Remote caller and thread-safe command queue, so remote commands run on the game thread with the caller\'s group permissions\\n- **Require Verified Ids** setting and **Mark Player Id Verified** function, so owner ids only count after your game has authenticated the player\\n- **Rpc Burst**, **Rpc Refill Per Second**, **Max List Rpc Items** and **Players Save Interval Seconds** settings\\n\\n## **FIXED**\\n\\n- Temporary `Session_N` ids are rejected for ban, whitelist and setgroup\\n- Sanction duration is capped\\n- Data that failed to load is no longer overwritten on save\\n- The hosting player on a listen server is never rejected by the player checks\\n- Admin client requests are rate limited and large lists are capped, so a client can no longer flood the server\\n- `Players.json` is saved at most every 30 seconds by default, which avoids hitches on servers with many known players\\n- Creating a token for your own group works, and refusals explain why"},{"id":"1-0-1","metadata":{"permalink":"/changelog/1-0-1","source":"@site/changelog/2026-10-24-1-0-1.md","title":"Server Admin Core 1.0.1","description":"GENERAL","date":"2026-10-24T00:00:00.000Z","tags":[],"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Server Admin Core 1.0.1","slug":"1-0-1"},"unlisted":false,"prevItem":{"title":"Server Admin Core 1.1.0","permalink":"/changelog/1-1-0"}},"content":"## **GENERAL**\\n\\n- Kicked players now get to see why they were kicked\\n- **On Auto Kick Warning** now includes the full warning **Message**\\n\\n## **ADDED**\\n\\n- **On Auto Kick Warning Cancelled** event\\n- **On Kicked** event on the ServerAdminCore Player Component\\n- **On Local Player Kicked** event on the ServerAdminCore subsystem\\n- **Was Kicked**, **Get Last Kick Reason** and **Clear Last Kick Reason** functions"}]}}')}}]);